<template>
  <section class="space-y-5"><div><p class="text-xs font-bold uppercase tracking-wider text-blue-300">Dispatch schedule</p><h1 class="mt-1 text-3xl font-bold text-white">Calendar</h1></div><div v-for="group in groups" :key="group.date" class="pc-card"><h2 class="font-semibold text-white">{{ date(group.date) }}</h2><NuxtLink v-for="item in group.items" :key="item.id" :to="item.href" class="mt-3 flex flex-wrap justify-between gap-4 rounded-xl border border-white/5 p-4 hover:border-blue-400/30"><div><p class="font-semibold text-white">{{ item.title }}</p><p class="mt-1 text-sm text-slate-400">{{ item.subtitle||'No detail' }}</p></div><span class="text-xs uppercase text-blue-300">{{ label(item.status) }}</span></NuxtLink></div><p v-if="error" class="pc-card text-red-300">{{ error }}</p><p v-if="!groups.length&&!error" class="pc-card text-slate-500">No scheduled work.</p></section>
</template>
<script setup lang="ts">
definePageMeta({layout:'partner-workspace',middleware:['auth']});const {apiFetch}=useApi();const items=ref<any[]>([]);const error=ref('');const label=(v:string)=>v?.replaceAll('_',' ')||'unknown';const date=(v:string)=>new Date(`${v}T00:00:00`).toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});const groups=computed(()=>{const map=new Map<string,any[]>();for(const item of items.value)map.set(item.date,[...(map.get(item.date)||[]),item]);return [...map].map(([date,rows])=>({date,items:rows}))});onMounted(async()=>{try{items.value=(await apiFetch<any>('/partner/calendar')).items||[]}catch(e:any){error.value=e?.data?.detail||e?.message}})
</script>
